    public final void setVisible_InGame_CivInfo(boolean visible) {
                        try {
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_INFO).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_INFO_STATS).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_DIPLOMACY).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_DIPLO_ORACTIONS).setVisibleM(visible);
            if (visible) {
                int nCivID = CFG.getActiveCivInfo_BasedOnActiveProvinceID(CFG.core.getActiveProvID());
                if (nCivID != CFG.getActiveCivInfoId()) {
                    CFG.setActiveCivInfoId(nCivID);
                }
                CFG.updateActiveCivilizationInfoInGame();
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_INFO).updateLang();
                if (this.getInGame_ProvincemMore_Visible()) {
                    this.setVisible_InGame_ProvinceMore(false, false);
                }
                if (this.getVisible_InGame_View_Stats()) {
                    this.setVisible_InGame_View(false);
                }
            }
            this.setOrderOfMenu_InGame_CivInfo();
        }
        catch (Exception exception) {
            
        }
    }

    public final void setVisible_InGame_Civ_Decisions(boolean visible) {
        if (visible) {
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_DECISIONS).actionCloseMenu();
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_DECISIONS).setVisibleM(visible);
            this.rebuildInGame_Civ_Info_Decisions();
            this.INGAME_CIV_INFO_ACTIONS_VISIBLE = !this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_OPINIONS).getVisibleM();
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_DIPLO_ORACTIONS).actionCloseMenu();
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_ACTIONS).actionCloseMenu();
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_OPINIONS).actionCloseMenu();
        } else {
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_DECISIONS).actionCloseMenu();
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_DIPLO_ORACTIONS).setVisibleM(!visible);
            if (this.INGAME_CIV_INFO_ACTIONS_VISIBLE) {
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_ACTIONS).setVisibleM(!visible);
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_OPINIONS).actionCloseMenu();
            } else {
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_OPINIONS).setVisibleM(!visible);
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_CIV_ACTIONS).actionCloseMenu();
            }
        }
    }

