    public final void updateInGameRTO(boolean visible) {
        if (this.INGAME_RTO >= 0 && this.INGAME_RTO_BOT >= 0) {
            if (visible) {
                this.menus.get(this.IN_GAME_MENU).set(this.INGAME_RTO, new Menu_InGame_RTO2());
                this.menus.get(this.IN_GAME_MENU).set(this.INGAME_RTO_BOT, new Menu_InGame_RTO_Bot2());
                int tHeight = CFG.GAMEHEIGHT - this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getPosY() - this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO_BOT).getHeightM() - CFG.BUTTON_H - CFG.PADD * 2 - CFG.BUTTON_H - CFG.PADD * 2;
                if (this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getMenuElem(this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getMenuElemsSize() - 1).getPosY() + this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getMenuElem(this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getMenuElemsSize() - 1).getHeightE() < tHeight) {
                    tHeight = this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getMenuElem(this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getMenuElemsSize() - 1).getPosY() + this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getMenuElem(this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getMenuElemsSize() - 1).getHeightE();
                }
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).setHeight(tHeight);
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).updateMenuElements_IsInView();
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO_BOT).setPosX(this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getPosX());
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO_BOT).setPosY(this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getPosY() + this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getHeightM() + 1);
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO_BOT).setWidth(this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).getWidthM());
            }
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_RTO_BOT).setVisibleM(visible && CFG.settingsGD.showOrderOfMovesView);
        }
    }

