    public final void update() {
        try {
            if (this.fromViewID >= 0) {
                this.animationChangeViewPosX = CFG.changeAnimationPos(this.animationStepID++, this.animationChangeViewPosX, this.backAnimation, CFG.GAMEWIDTH);
                if (Math.abs(this.animationChangeViewPosX) >= (float)CFG.GAMEWIDTH || CFG.iNumOfFPS < 22) {
                    this.resetChangeViewMode();
                }
            }
            if (CFG.isAndroid() && this.get_MenuElementHover_IsInView() && hoverMobileTime < System.currentTimeMillis() - (long)HOVER_MOBILE_TIME_VISIBLE) {
                this.resetHoverActive();
            }
            for (int i = 0; i < this.getActiveMenu().size(); ++i) {
                if (!this.getActiveMenu().get(i).getScrollableY() && !this.getActiveMenu().get(i).getScrollableX()) continue;
                this.getActiveMenu().get(i).update();
            }
            this.slideMap_ActionMove.update_ActionMove_SlideMap();
        }
        catch (Exception exception) {
            
        }
    }

    public final void resetMobileHover() {
        try {
            if (CFG.isAndroid()) {
                this.resetHoverActive();
            }
        }
        catch (Exception exception) {
            
        }
    }

    public final void drawMM(SpriteBatch oSB) {
        try {
            if (this.fromViewID < 0) {
                this.drawMM(oSB, this.viewID, 0);
            } else {
                this.drawMM(oSB, this.fromViewID, (int)this.animationChangeViewPosX);
                this.drawMM(oSB, this.toViewID, (int)this.animationChangeViewPosX + CFG.GAMEWIDTH * (this.backAnimation ? -1 : 1));
            }
            if (CFG.achievementGD != null) {
                CFG.achievementGD.draw(oSB, 0, 0);
                if (CFG.achievementGD.canBeDisposed()) {
                    CFG.achievementGD = null;
                }
            }
            if (CFG.toastM != null && CFG.toastM.getInView()) {
                this.drawToastGradient(oSB);
                CFG.toastM.draw(oSB);
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    public final void drawToastGradient(SpriteBatch oSB) {
        if (TOAST_TIME + (long)ANIMATION_TIME >= CFG.currentTimeMillis) {
            float fAlpha = 0.8f - 0.8f * ((float)(CFG.currentTimeMillis - TOAST_TIME) / (float)ANIMATION_TIME);
            oSB.setColor(new Color(Colors.COLOR_GRADIENT_BG_BLUE.r, Colors.COLOR_GRADIENT_BG_BLUE.g, Colors.COLOR_GRADIENT_BG_BLUE.b, fAlpha));
            IMGManager.getIMG(Images.gradientXY).draw(oSB, CFG.GAMEWIDTH / 4, CFG.GAMEHEIGHT - CFG.BUTTON_H * 2, CFG.GAMEWIDTH / 2, CFG.BUTTON_H * 2);
            oSB.setColor(Color.WHITE);
        }
    }

    public final void updateEleemntHover_Animation() {
        if (ME_Hover_v2.ANIMATION_ALPHA < 1.0f) {
            ME_Hover_v2.ANIMATION_PADDING = (float)(CFG.PADD * 2) - (float)(CFG.PADD * 2) * ((ME_Hover_v2.ANIMATION_ALPHA += (float)(System.currentTimeMillis() - ME_Hover_v2.ANIMATION_TIME) / (float)ME_Hover_v2.ANIMATION_INTERVAL) * 1.65f);
            if (ME_Hover_v2.ANIMATION_PADDING < 0.0f) {
                ME_Hover_v2.ANIMATION_PADDING = 0.0f;
            }
            if (ME_Hover_v2.ANIMATION_ALPHA > 1.0f) {
                ME_Hover_v2.ANIMATION_ALPHA = 1.0f;
            }
        }
    }

    public final void resetFontScales() {
        for (int i = CFG.fontMain.size() - 1; i >= 0; --i) {
            CFG.fontMain.get(i).getData().setScale(1.0f);
        }
    }

    public final void drawMM(SpriteBatch oSB, int menuID, int iTranslateX) {
        long menuStart = 0L;
        try {
            for (int i = this.menus.get(menuID).size() - 1; i >= 0; --i) {
                if (!this.menus.get(menuID).get(this.orderOfMenu.get(menuID).get(i)).getVisibleM()) continue;
                menuStart = System.currentTimeMillis();
                this.menus.get(menuID).get(this.orderOfMenu.get(menuID).get(i)).draw(oSB, iTranslateX, this.dialogMenu.getVisibleM() ? false : (this.keyboardMode ? false : this.orderOfMenu.get(menuID).get(i) == this.activeMenuID));
                long menuTime = System.currentTimeMillis() - menuStart;
                if (menuTime > 50) {
                    CFG.LOG("PERF", "[drawMM] menuIdx:" + this.orderOfMenu.get(menuID).get(i) + " time:" + menuTime + "ms");
                }
            }
            CFG.tutorialManager.draw(oSB, iTranslateX, 0);
        }
        catch (Exception exception) {
            
        }
        try {
            long hoverStart = System.currentTimeMillis();
            if (this.hoverActiveMenuID >= 0 && this.hoverActiveMenuElemID >= 0) {
                this.updateEleemntHover_Animation();
                this.getActiveMenu().get(this.hoverActiveMenuID).drawHoverM(oSB, iTranslateX, 0, this.hoverActiveMenuElemID);
            } else if (this.provHoverInfo != null) {
                this.updateEleemntHover_Animation();
                this.provHoverInfo.drawProvinceInfo(oSB, Touch.getMousePosX() + this.getHover_ExtraPosX(), Touch.getMousePosY() + this.getHover_ExtraPosY());
            }
            long hoverTime = System.currentTimeMillis() - hoverStart;
            if (hoverTime > 20) {
                CFG.LOG("PERF", "[drawMM] hover:" + hoverTime + "ms");
            }
            long overlaysStart = System.currentTimeMillis();
            if (this.colorPicker.getVisible()) {
                this.colorPicker.draw(oSB, iTranslateX);
            }
            if (this.keyboard.getVisibleM()) {
                this.keyboard.draw(oSB, iTranslateX, this.keyboardMode);
            }
            if (this.dialogMenu.getVisibleM()) {
                this.dialogMenu.draw(oSB, iTranslateX, true);
            }
            this.dragCiv.draw(oSB, iTranslateX);
            long overlaysTime = System.currentTimeMillis() - overlaysStart;
            if (overlaysTime > 20) {
                CFG.LOG("PERF", "[drawMM] overlays:" + overlaysTime + "ms");
            }
        }
        catch (Exception exception) {
            
        }
    }

    public final boolean get_MenuElementHover_IsInView() {
        try {
            if (this.hoverActiveMenuID >= 0 && this.hoverActiveMenuElemID >= 0 && !this.getActiveMenu().get(this.hoverActiveMenuID).getMenuElem(this.hoverActiveMenuElemID).getMenuElemHover_IsNull()) {
                return true;
            }
            return this.provHoverInfo != null;
        }
        catch (Exception ex) {
            return this.provHoverInfo != null;
        }
    }

