    public final boolean actionMove(int nPosX, int nPosY) {
        this.isWarDetailsValid();
        try {
            if (this.activeMenuID >= 0 && this.activeMenuElemeID >= 0) {
                hoverMobileTime = System.currentTimeMillis();
            }
            if (this.colorPickerMode) {
                this.colorPicker.touch(nPosX, nPosY);
                CFG.setRenderO(true);
                return true;
            }
            if (this.textSliderMode) {
                this.actionMoveTextSliderY(nPosX, nPosY);
                this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).setScrollPosY(nPosY);
            } else {
                if (this.sliderMode) {
                    this.actionMoveSlider(nPosX, nPosY);
                    return true;
                }
                if (this.slideMapMode) {
                    CFG.slidePosX = nPosX;
                    CFG.slidePosY = nPosY;
                } else {
                    if (this.sliderMenuResizeMode) {
                        this.actionMoveResize(nPosX, nPosY);
                        return true;
                    }
                    if (this.sliderMenuTitleMode) {
                        this.actionMoveTitle(nPosX, nPosY);
                        return true;
                    }
                    if (this.sliderMenuMode) {
                        this.actionMoveMenu(nPosX, nPosY);
                        this.getActiveMenu().get(this.activeMenuID).setScrollPosY(nPosY);
                        this.getActiveMenu().get(this.activeMenuID).setScrollPosX(nPosX);
                        return true;
                    }
                }
            }
            if (this.flagEditorMode) {
                if (CFG.flagEditorMode == CFG.FlagEditorMode.PENCIL) {
                    for (int i = 0; i < this.getActiveMenu().get(this.activeMenuID).getMenuElemsSize(); ++i) {
                        if (nPosX < this.getActiveMenu().get(this.activeMenuID).getMenuElem(i).getPosXE() + this.getActiveMenu().get(this.activeMenuID).getPosX() || nPosX > this.getActiveMenu().get(this.activeMenuID).getMenuElem(i).getPosXE() + this.getActiveMenu().get(this.activeMenuID).getMenuElem(i).getWidthE() + this.getActiveMenu().get(this.activeMenuID).getPosX() || nPosY < this.getActiveMenu().get(this.activeMenuID).getMenuElem(i).getPosY() + this.getActiveMenu().get(this.activeMenuID).getPosY() || nPosY > this.getActiveMenu().get(this.activeMenuID).getMenuElem(i).getPosY() + this.getActiveMenu().get(this.activeMenuID).getMenuElem(i).getHeightE() + this.getActiveMenu().get(this.activeMenuID).getPosY()) continue;
                        this.actionElem(this.activeMenuID, i);
                        return true;
                    }
                }
                return true;
            }
            if (this.graphMode) {
                this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).updateSlider(-this.getActiveMenu().get(this.activeMenuID).getPosX() + nPosX);
                return true;
            }
            if (this.graphButtonMode) {
                if (this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).isMoveable()) {
                    this.actionMoveTextSliderY(nPosX, nPosY);
                    this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).setScrollPosY(nPosY);
                    if (this.updateSliderMenuPosY) {
                        this.iMenuStartPosY = (int)this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getCurrLong() - nPosY;
                        this.updateSliderMenuPosY = false;
                    } else {
                        this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).setCurr((long)(this.iMenuStartPosY + nPosY));
                    }
                }
                return true;
            }
            if (this.graphButtonMode2) {
                if (this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).isMoveable()) {
                    if (this.updateSliderMenuPosY) {
                        this.iMenuStartPosY = (int)this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getCurrLong() - nPosY;
                        this.updateSliderMenuPosY = false;
                    } else {
                        this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).setCurr((long)(this.iMenuStartPosY + nPosY));
                    }
                }
                return true;
            }
            if (this.graphButtonModeX) {
                if (this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).isMoveable()) {
                    this.actionMoveTextSliderX(nPosX, nPosY);
                    this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).setScrollPosY(nPosX);
                    if (this.updateSliderMenuPosX) {
                        this.iSliderMenuStartPosX = (int)this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getCurrLong() - nPosX;
                        this.updateSliderMenuPosX = false;
                    } else {
                        this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).setCurr((long)(this.iSliderMenuStartPosX + nPosX));
                    }
                }
                return true;
            }
            if (this.activeMenuElemeID >= 0) {
                return true;
            }
            if (this.sliderMenuCloseMode) {
                return true;
            }
            if (this.dialogMenu != null && this.dialogMenu.getVisibleM()) {
                return true;
            }
            if (this.keyboardMode) {
                return true;
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
        return false;
    }

