    public final boolean actionUp(int nPosX, int nPosY, int nPointer, int button) {
        this.isWarDetailsValid();
        System.out.println("MenuManager: actionUp " + nPosX + " " + nPosY + " button:" + button + " activeMenuID:" + this.activeMenuID + " activeMenuElemeID:" + this.activeMenuElemeID);
        try {
            if (this.dialogMenu != null && this.dialogMenu.getVisibleM()) {
                if (this.activeMenuElemeID >= 0 && this.dialogMenu.getMenuElem(this.activeMenuElemeID).getIsClickable() && nPosX >= this.dialogMenu.getMenuElem(this.activeMenuElemeID).getPosXE() && nPosX <= this.dialogMenu.getMenuElem(this.activeMenuElemeID).getPosXE() + this.dialogMenu.getMenuElem(this.activeMenuElemeID).getWidthE() && nPosY >= this.dialogMenu.getMenuElem(this.activeMenuElemeID).getPosY() && nPosY <= this.dialogMenu.getMenuElem(this.activeMenuElemeID).getPosY() + this.dialogMenu.getMenuElem(this.activeMenuElemeID).getHeightE()) {
                    CFG.SFXManager.playSound(SFXManager.SFX_CLICK2);
                    this.dialogMenu.actionEL(this.activeMenuElemeID);
                }
                return true;
            }
            if (this.keyboardMode) {
                if (this.activeMenuElemeID >= 0 && this.keyboard.getMenuElem(this.activeMenuElemeID).getIsClickable() && nPosX >= this.keyboard.getMenuElem(this.activeMenuElemeID).getPosXE() + this.keyboard.getPosX() && nPosX <= this.keyboard.getMenuElem(this.activeMenuElemeID).getPosXE() + this.keyboard.getPosX() + this.keyboard.getMenuElem(this.activeMenuElemeID).getWidthE() && nPosY >= this.keyboard.getMenuElem(this.activeMenuElemeID).getPosY() + this.keyboard.getPosY() && nPosY <= this.keyboard.getMenuElem(this.activeMenuElemeID).getPosY() + this.keyboard.getPosY() + this.keyboard.getMenuElem(this.activeMenuElemeID).getHeightE()) {
                    try {
                        CFG.SFXManager.playSound(this.keyboard.getMenuElem(this.activeMenuElemeID).getSFXElem());
                    }
                    catch (IndexOutOfBoundsException ex) {
                        CFG.SFXManager.playSound(SFXManager.SFX_CLICK);
                    }
                    this.keyboard.actionEL(this.activeMenuElemeID);
                }
                return true;
            }
            if (this.colorPickerMode) {
                this.colorPicker.touch(nPosX, nPosY);
                this.colorPicker.touchUp();
                CFG.SFXManager.playSound(SFXManager.SFX_CLICK);
                return true;
            }
            if (this.sliderMenuCloseMode) {
                this.actionUpClose(nPosX, nPosY);
                CFG.SFXManager.playSound(SFXManager.SFX_CLICK3);
                return true;
            }
            if (this.sliderMode) {
                this.sliderMode = false;
                if (this.getActiveMenuElement().getIsClickable()) {
                    if (button == 1) {
                        this.actionElemPPM(this.activeMenuID, this.activeMenuElemeID);
                    } else {
                        this.actionElem(this.activeMenuID, this.activeMenuElemeID);
                    }
                }
                return true;
            }
            if (this.graphMode) {
                this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).updateSlider(-this.getActiveMenu().get(this.activeMenuID).getPosX() + nPosX);
                return true;
            }
            if (this.graphButtonMode) {
                if (this.iMenuActionDownPosY >= nPosY - CFG.PADD && this.iMenuActionDownPosY <= nPosY + CFG.PADD && this.iMenuActionDownPosX >= nPosX - CFG.PADD && this.iMenuActionDownPosX <= nPosX + CFG.PADD) {
                    this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).updateSlider(nPosY);
                    this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).setAnotherView(!this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getAnotherView());
                    CFG.SFXManager.playSound(this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getSFXElem());
                } else {
                    this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).scrollTheMenu();
                }
                if (this.getActiveMenuElement().getIsClickable()) {
                    if (button == 1) {
                        this.actionElemPPM(this.activeMenuID, this.activeMenuElemeID);
                    } else {
                        this.actionElem(this.activeMenuID, this.activeMenuElemeID);
                    }
                }
                return true;
            }
            if (this.graphButtonMode2) {
                if ((float)nPosY - (float)CFG.PADD * CFG.GUI_SCALE <= (float)this.iMenuActionDownPosY && (float)nPosY + (float)CFG.PADD * CFG.GUI_SCALE >= (float)this.iMenuActionDownPosY && (float)nPosX - (float)CFG.PADD * CFG.GUI_SCALE <= (float)this.iMenuActionDownPosX && (float)nPosX + (float)CFG.PADD * CFG.GUI_SCALE >= (float)this.iMenuActionDownPosX) {
                    this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).updateSlider(-this.getActiveMenu().get(this.activeMenuID).getPosY() + nPosY);
                }
                return true;
            }
            if (this.graphButtonModeX) {
                if ((float)this.iMenuActionDownPosY >= (float)nPosY - (float)CFG.PADD * CFG.GUI_SCALE && (float)this.iMenuActionDownPosY <= (float)nPosY + (float)CFG.PADD * CFG.GUI_SCALE && (float)this.iMenuActionDownPosX >= (float)nPosX - (float)CFG.PADD * CFG.GUI_SCALE && (float)this.iMenuActionDownPosX <= (float)nPosX + (float)CFG.PADD * CFG.GUI_SCALE) {
                    this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).setAnotherView(!this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getAnotherView());
                } else if (this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).isMoveable()) {
                    this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).scrollTheMenu();
                }
                return true;
            }
            if (this.textSliderMode) {
                this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).scrollTheMenu();
            }
            if (this.activeMenuElemeID >= 0 && this.activeMenuID >= 0 && (!this.sliderMenuMode || this.iMenuActionDownPosY >= nPosY - CFG.PADD && this.iMenuActionDownPosY <= nPosY + CFG.PADD && this.iMenuActionDownPosX >= nPosX - CFG.PADD && this.iMenuActionDownPosX <= nPosX + CFG.PADD) && this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getIsClickable() && nPosX >= this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getPosXE() + this.getActiveMenu().get(this.activeMenuID).getMenuPosX() && nPosX <= this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getPosXE() + this.getActiveMenu().get(this.activeMenuID).getMenuPosX() + this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getWidthE() && nPosY >= this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getPosY() + this.getActiveMenu().get(this.activeMenuID).getMenuPosY() && nPosY <= this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getPosY() + this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getHeightE() + this.getActiveMenu().get(this.activeMenuID).getMenuPosY()) {
                try {
                    CFG.SFXManager.playSound(this.getActiveMenu().get(this.activeMenuID).getMenuElem(this.activeMenuElemeID).getSFXElem());
                }
                catch (IndexOutOfBoundsException ex) {
                    CFG.SFXManager.playSound(SFXManager.SFX_CLICK);
                }
                if (button == 1) {
                    this.actionElemPPM(this.activeMenuID, this.activeMenuElemeID);
                } else {
                    this.actionElem(this.activeMenuID, this.activeMenuElemeID);
                }
                return true;
            }
            if (this.sliderMenuMode) {
                this.getActiveMenu().get(this.activeMenuID).scrollTheMenu();
            }
        }
        catch (IndexOutOfBoundsException indexOutOfBoundsException) {
        }
        catch (NullPointerException nullPointerException) {
            
        }
        return false;
    }

    private final void actionUpClose(int nPosX, int nPosY) {
        if (this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getVisibleM() && this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getCloseable() && nPosX >= this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getPosX() + this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getWidthM() - IMGManager.getIMG(Images.btnClose).getWidth() && nPosX <= this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getPosX() + this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getWidthM()) {
            if (this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getTitleM() == null) {
                if (nPosY >= this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getPosY() && nPosY <= this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getPosY() + IMGManager.getIMG(Images.btnClose).getHeight()) {
                    this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).actionCloseMenu();
                }
            } else if (nPosY >= this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getPosY() - this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getTitleM().getHeightT() && nPosY <= this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getPosY() + IMGManager.getIMG(Images.btnClose).getHeight() - this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).getTitleM().getHeightT()) {
                this.getActiveMenu().get(this.getActiveOrder(this.activeMenuID)).actionCloseMenu();
            }
        }
    }

