    public final void setVisible_InGame_FlagAction(boolean visible) {
                        try {
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_BOT).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_BOT_RIGHT_LEFT).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_GRAPH_MODES).setVisibleM(visible);
            if (visible) {
                this.menus.get(this.IN_GAME_MENU).set(this.INGAME_FLAG_ACTION_BOT_LEFT, new Menu_InGame_FA_Budget());
                this.menus.get(this.IN_GAME_MENU).set(this.INGAME_FLAG_ACTION_BOT_RIGHT_RIGHT, new Menu_InGame_FA_RightRank());
                this.menus.get(this.IN_GAME_MENU).set(this.INGAME_FLAG_ACTION_STATS, new Menu_InGame_FA_Stats());
                this.menus.get(this.IN_GAME_MENU).set(this.INGAME_FLAG_ACTION_BOT_RIGHT_LEFT, new Menu_InGame_FA_GraphBotCenter());
                this.setVisible_InGame_Budget(false);
            }
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_BOT_LEFT).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_BOT_RIGHT_RIGHT).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_STATS).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_BOT_RIGHT_LEFT).setVisibleM(visible);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_CONSOLE).setVisibleM(false);
            if (SFXManager.isPlayingConsoleMusic) {
                CFG.SFXManager.randomizePlayList();
                CFG.SFXManager.loadNextMusic();
            }
            this.setOrderOfMenu_InGame_FlagAction();
            Render.updateRenderer();
        }
        catch (Exception exception) {
            
        }
    }

