    public final void setVisible_InGame_Budget(boolean visible) {
        if (!visible) {
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_BUDGET).setVisibleM(visible);
        } else {
            if (this.getVisible_InGame_FlagAction()) {
                this.setVisible_InGame_FlagAction(false);
            }
            int tPosX = this.menus.get(this.IN_GAME_MENU).get(this.INGAME_BUDGET).getPosX();
            int tPosY = this.menus.get(this.IN_GAME_MENU).get(this.INGAME_BUDGET).getPosY();
            int tWidth = this.menus.get(this.IN_GAME_MENU).get(this.INGAME_BUDGET).getWidthM();
            this.menus.get(this.IN_GAME_MENU).set(this.INGAME_BUDGET, new Menu_InGame_Budget());
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_BUDGET).setPosX(tPosX);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_BUDGET).setPosY(tPosY);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_BUDGET).setWidth(tWidth);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_BUDGET).setVisibleM(true);
            this.setOrderOfMenuID(this.INGAME_BUDGET);
        }
    }

