    public final void setVisible_InGame_FlagAction_Console(boolean visible) {
        this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION).setVisibleM(true);
        this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_STATS).setVisibleM(!visible);
        this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_BOT).setVisibleM(!visible);
        this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_BOT_RIGHT_LEFT).setVisibleM(!visible);
        this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_BOT_RIGHT_RIGHT).setVisibleM(!visible);
        this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_BOT_LEFT).setVisibleM(!visible);
        this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_GRAPH_MODES).setVisibleM(!visible);
        this.menus.get(this.IN_GAME_MENU).get(this.INGAME_FLAG_ACTION_CONSOLE).setVisibleM(visible);
        if (visible) {
            if (GameValues.gvCommands.PLAY_CONSOLE_MUSIC) {
                CFG.SFXManager.playConsoleMusic();
            }
            Render.updateRenderer();
        } else if (GameValues.gvCommands.PLAY_CONSOLE_MUSIC) {
            CFG.SFXManager.randomizePlayList();
            CFG.SFXManager.loadNextMusic();
        }
        this.setOrderOfMenu_InGame_FlagAction();
        Render.updateRenderer();
    }

