    public final void updateInGameTopRank(int nCivID) {
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(6).setTextE("" + CFG.core.getCiv(nCivID).getRankPos());
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(6).setVisibleE(true);
    }

    public final void updateInGameTopMoney(int nCivID) {
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(1).setWidthE(1);
        if (CFG.core.getCiv(nCivID).getGold() > (long)GameValues.gvInGame.SHORT_TREASURY_IF_OVER) {
            this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(1).setTextE("" + CFG.getNumber_SHORT(CFG.core.getCiv(nCivID).getGold()));
        } else {
            this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(1).setTextE("" + CFG.getNumberWthSpaces("" + CFG.core.getCiv(nCivID).getGold()));
        }
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(1).setVisibleE(true);
        Menu_InGame_2.updateOverBudget();
    }

    public final void updateInGameTopMovePoints(int nCivID) {
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(2).setWidthE(1);
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(2).setTextE(("" + (float)CFG.core.getCiv(nCivID).getMovemPoints() / 10.0f).replaceAll(",", "."));
        int value = CFG.gameAction.getCivMovementPoints(CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId());
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(2).setText2("+" + ("" + (float)value / 10.0f).replaceAll(",", "."));
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(2).setVisibleE(true);
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(13).setWidthE(1);
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(13).setTextE("" + CFG.getNumber_SHORT(CFG.core.getCiv(CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId()).getNumberOfUnits()));
        int militaryCost = CFG.gameUpdate.getMilitarySpending(CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId(), CFG.core.getCiv((int)CFG.core.getPlayer((int)CFG.PLAYER_TURN_ID).getCivId()).iBudget);
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(13).setText2(("" + Math.max(0, Math.min(9999, militaryCost)) + "%").replaceAll(",", "."));
        this.menus.get(this.IN_GAME_MENU).get(0).getMenuElem(13).setVisibleE(true);
    }

