    public final boolean isWarDetailsValid() {
        if (this.INGAME_WAR_DETAILS < 0) return false;
                        try {
            if (this.menus.get(this.IN_GAME_MENU).get(this.INGAME_WAR_DETAILS).getVisibleM()) {
                if (CFG.core.getWarsSize() == 0) {
                    this.setVisibleInGame_WarDetails(false);
                    return false;
                }
                return true;
            }
        } catch (Exception e) {}
        return false;
    }

    public final void setVisibleInGame_WarDetails(boolean visible) {
        if (this.INGAME_WAR_DETAILS >= 0) {
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_WAR_DETAILS).setVisibleM(visible);
            if (!visible) {
                if (this.activeMenuID == this.INGAME_WAR_DETAILS) {
                    this.activeMenuID = -1;
                    this.activeMenuElemeID = -1;
                }
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_WAR_DETAILS).stopScrolling();
                this.sliderMenuMode = false;
                this.sliderMenuTitleMode = false;
                this.sliderMenuResizeMode = false;
                this.sliderMenuCloseMode = false;
            } else if (CFG.core.getWarsSize() == 0) {
                this.setVisibleInGame_WarDetails(false);
            }
        }
    }

