    public final void rebuildInGame_Event() {
        try {
            try {
                if (CFG.eventsManager.getEvent((int)Menu_InGame_Event.EVENT_ID).tempTAG != null && !CFG.eventsManager.getEvent((int)Menu_InGame_Event.EVENT_ID).tempTAG.equals("")) {
                    for (int a = 0; a < EventTemplatesMGR.eventTemplates.size(); ++a) {
                        if (!EventTemplatesMGR.eventTemplates.get((int)a).TAG.equals(CFG.eventsManager.getEvent((int)Menu_InGame_Event.EVENT_ID).tempTAG)) continue;
                        Menu_InGame_Event2.TLID = a;
                        this.menus.get(this.IN_GAME_MENU).set(this.INGAME_EVENT, new Menu_InGame_Event2());
                        this.menus.get(this.IN_GAME_MENU).get(this.INGAME_EVENT).setVisibleM(true);
                        this.setOrderOfMenuID(this.INGAME_EVENT);
                        this.menus.get(this.IN_GAME_MENU).get(this.INGAME_EVENT).updateMenuElements_IsInView();
                        return;
                    }
                }
            }
            catch (Exception a) {
                
            }
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_EVENT).setVisibleM(false);
            int tPosX = this.menus.get(this.IN_GAME_MENU).get(this.INGAME_EVENT).getPosX();
            int tPosY = this.menus.get(this.IN_GAME_MENU).get(this.INGAME_EVENT).getPosY();
            this.menus.get(this.IN_GAME_MENU).set(this.INGAME_EVENT, new Menu_InGame_Event());
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_EVENT).setPosX(tPosX);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_EVENT).setPosY(tPosY);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_EVENT).setVisibleM(true);
            this.setOrderOfMenuID(this.INGAME_EVENT);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_EVENT).updateMenuElements_IsInView();
        }
        catch (Exception exr) {
            CFG.exceptionStack(exr);
        }
        try {
            CFG.SFXManager.playSound(SFXManager.SFX_EVENT);
        }
        catch (Exception exception) {
            
        }
    }

