    public final void updateInGame_ActionInfo_Recruit() {
        try {
            long armyIn = 0L;
            try {
                armyIn = CFG.core.getProv(CFG.core.getActiveProvID()).getArmyID(0);
            }
            catch (Exception exception) {
                
            }
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_ACTION_INFO_CHOOSE_PROVINCE).getMenuElem(0).setWidthE(1);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_ACTION_INFO_CHOOSE_PROVINCE).getMenuElem(0).setTextE(CFG.lang.get("Recruit") + " " + this.getInGame_ProvRecruitSlider().getCurr() + " " + CFG.lang.get("Units") + ". [" + (armyIn + this.getInGame_ProvRecruitSlider().getCurr()) + "]");
            long totalCost = 0L;
            int totalCostMovement = 0;
            for (int i = 0; i < Core.AMRCT.size(); ++i) {
                totalCost += (long)(Core.AMRCT.get((int)i).SPR * CFG.gCARR(Core.AMRCT.get((int)i).OBC));
                if (CFG.core.getCiv(CFG.core.getProv(Core.AMRCT.get((int)i).OBC).getCivId()).isRAIP(Core.AMRCT.get((int)i).OBC) >= 0) continue;
                totalCostMovement += CFG.ideologiesMgr.getIdeologyID((int)CFG.core.getCiv((int)CFG.core.getProv((int)Core.AMRCT.get((int)i).OBC).getCivId()).getIdeology()).COST_OF_RECRUIT;
            }
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_ACTION_INFO_CHOOSE_PROVINCE).getMenuElem(1).setTextE("-" + (float)totalCostMovement / 10.0f);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_ACTION_INFO_CHOOSE_PROVINCE).getMenuElem(2).setWidthE(1);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_ACTION_INFO_CHOOSE_PROVINCE).getMenuElem(2).setTextE(CFG.lang.get("Cost") + ": " + CFG.getNumberWthSpaces("" + totalCost));
            int nRecruitmentTurns = CFG.core.getCiv(CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId()).getRecruitmentTurns();
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_ACTION_INFO_CHOOSE_PROVINCE).getMenuElem(3).setTextE(nRecruitmentTurns + " " + (nRecruitmentTurns > 1 ? CFG.lang.get("Turns") : CFG.lang.get("Turn")));
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_ACTION_INFO_CHOOSE_PROVINCE).getMenuElem(5).setWidthE(1);
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_ACTION_INFO_CHOOSE_PROVINCE).getMenuElem(5).setCurr(this.getInGame_ProvRecruitSlider().getCurr());
        }
        catch (Exception exception) {
            
        }
    }

