    public final void setVisible_InGame_ProvinceMore(boolean visible, boolean savePosY) {
        try {
            if (visible && BuildingsManager.iBuildInProvinceID >= 0 && (CFG.core.getProv(BuildingsManager.iBuildInProvinceID).getCivId() == CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId() || CFG.core.getCiv(CFG.core.getProv(BuildingsManager.iBuildInProvinceID).getCivId()).getPuppetOfCiv() == CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId())) {
                int tY = this.menus.get(this.IN_GAME_MENU).get(this.INGAME_PROVINCE_MORE).getMenuPosY();
                this.menus.get(this.IN_GAME_MENU).set(this.INGAME_PROVINCE_MORE, new Menu_InGame_Province_More());
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_PROVINCE_MORE).setVisibleM(visible);
                if (savePosY) {
                    this.menus.get(this.IN_GAME_MENU).get(this.INGAME_PROVINCE_MORE).setMenuPosY(tY);
                }
                if (this.getVisible_InGame_CivInfo()) {
                    this.setVisible_InGame_CivInfo(false);
                }
                if (this.getVisible_InGame_View_Stats()) {
                    this.setVisible_InGame_View(false);
                }
            } else {
                this.menus.get(this.IN_GAME_MENU).get(this.INGAME_PROVINCE_MORE).setVisibleM(visible);
            }
            if (visible) {
                this.setOrderOfMenuID(this.INGAME_PROVINCE_MORE);
            }
        }
        catch (Exception ex) {
            this.menus.get(this.IN_GAME_MENU).get(this.INGAME_PROVINCE_MORE).setVisibleM(visible);
        }
    }

